import {componentCSS} from './components.mjs';
import {esc,uid,themes,coverColors,defaultStyle,countWords,decodeText,splitChapters,newBook,blocksToHTML,makeEpub,validateBook} from './core.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const componentStyle=document.createElement('style');componentStyle.textContent=componentCSS();document.head.append(componentStyle);
let db,books=[],page='library',filter='all',search='',list=false,currentId=null,chapterIndex=0,editTab='text',dirty=false,modalResolve=null,busy=false,readTimer=null,imageTarget='cover',undo=[],saveTimer;
const today=()=>new Date().toLocaleDateString('sv-SE');
const current=()=>books.find(b=>b.id===currentId);
const toast=s=>{const t=$('#toast');t.textContent=s;t.style.display='block';clearTimeout(t.timer);t.timer=setTimeout(()=>t.style.display='none',4500)};
const statusNames={want:'想读',reading:'在读',done:'读完'};
const kindNames={chapter:'章',volume:'卷',section:'节',page:'自定义页'};
async function init(){db=await new Promise((resolve,reject)=>{const req=indexedDB.open('bookloom',1);req.onupgradeneeded=()=>req.result.createObjectStore('books',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});books=await new Promise((resolve,reject)=>{const r=db.transaction('books').objectStore('books').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});for(const b of books)normalize(b);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
function normalize(b){b.style={...defaultStyle(),...b.style};b.fonts??=[];b.notes??=[];b.stats??={seconds:0,days:{}};b.progress??={chapter:0,ratio:0};b.tags??='';b.folder??='';return b}
async function saveBook(b=current()){if(!b)return;b.updated=Date.now();await new Promise((resolve,reject)=>{const tx=db.transaction('books','readwrite');tx.objectStore('books').put(b);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});dirty=false;const status=$('#save-status');if(status)status.textContent='已保存到本机';}
function scheduleSave(){dirty=true;clearTimeout(saveTimer);const book=current();const s=$('#save-status');if(s)s.textContent='正在保存…';saveTimer=setTimeout(()=>saveBook(book).catch(e=>toast('保存失败，请立即备份：'+e.message)),400)}
function allWords(){return books.reduce((n,b)=>n+b.chapters.reduce((s,c)=>s+countWords(c.text),0),0)}
function nav(next){if(busy)return;clearInterval(readTimer);readTimer=null;page=next;render();window.scrollTo(0,0)}
function frame(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-icon">织</div><div><strong>书织</strong><small>BOOKLOOM STUDIO</small></div></div><nav class="nav"><button data-nav="library" class="${page==='library'?'active':''}"><i>▤</i>我的书库</button><button data-nav="workbench" class="${page==='editor'||page==='workbench'?'active':''}"><i>✎</i>精排工作台</button><button data-nav="stats" class="${page==='stats'?'active':''}"><i>◷</i>阅读足迹</button><button data-nav="settings" class="${page==='settings'?'active':''}"><i>⚙</i>设置与备份</button></nav><div class="side-note">每一个故事，都值得认真装帧。<br/><br/><span class="dot"></span>文件在浏览器本地处理<br/>请定期备份，避免清理浏览器后丢失。</div></aside><div class="workspace"><header class="topbar"><span>个人阅读空间 <span style="color:#bcc3b3;margin:0 13px">/</span> ${page==='library'?'我的书库':page==='reader'?'沉浸阅读':page==='stats'?'阅读足迹':page==='settings'?'设置与备份':'精排工作台'}</span><span class="local"><span class="dot"></span>本地优先 · 自在阅读</span></header><main>${content}</main></div></div>`}
function render(){if(page==='editor'&&!current())page='workbench';if(page==='reader'&&!current())page='library';$('#app').innerHTML=frame(page==='library'?library():page==='workbench'?workbench():page==='editor'?editor():page==='reader'?reader():page==='stats'?stats():settings());bindCommon();if(page==='library')bindLibrary();if(page==='workbench')bindWorkbench();if(page==='editor')bindEditor();if(page==='reader')bindReader();if(page==='settings')bindSettings();loadFonts();}
function bindCommon(){$$('[data-nav]').forEach(el=>el.onclick=()=>{if(el.dataset.nav==='workbench'&&current())nav('editor');else nav(el.dataset.nav)});$$('[data-action="import"]').forEach(el=>el.onclick=()=>$('#files').click());$$('[data-action="sample"]').forEach(el=>el.onclick=addSample);$$('[data-action="new"]').forEach(el=>el.onclick=newProject);$$('[data-open]').forEach(el=>el.onclick=()=>openBook(el.dataset.open,'editor'));$$('[data-read]').forEach(el=>el.onclick=()=>openBook(el.dataset.read,'reader'));$$('[data-export]').forEach(el=>el.onclick=()=>exportBook(books.find(b=>b.id===el.dataset.export)));$$('[data-delete]').forEach(el=>el.onclick=()=>deleteBook(el.dataset.delete));}
function coverHTML(b,cls=''){return `<div class="cover ${cls}" style="--book-color:${esc(b.coverColor||coverColors[0])};${b.coverVariant%3===1?'background-image:radial-gradient(ellipse at bottom, #ffffff22, transparent 65%);':''}${b.coverVariant%3===2?'background-image:linear-gradient(140deg,transparent 50%,#ffffff18 50%);':''}">${b.cover?`<img src="${safeData(b.cover)}" alt="${esc(b.title)}封面">`:`<span class="cover-title">${esc(b.title)}</span><span class="cover-author">${esc(b.author)} 著</span>`}</div>`}
function safeData(d){return typeof d==='string'&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(d)?d:''}
function card(b){const words=b.chapters.reduce((s,c)=>s+countWords(c.text),0);return `<article class="book-card">${coverHTML(b)}<div><h3>${esc(b.title)}</h3><p>${esc(b.author)} · ${(words/10000).toFixed(1)} 万字</p><div style="margin-top:8px"><span class="badge">${statusNames[b.status]||'想读'}</span>${b.folder?` <span class="status-text">${esc(b.folder)}</span>`:''}</div></div><div class="card-actions"><button data-read="${b.id}">阅读</button><button data-open="${b.id}">精排</button><button data-export="${b.id}" title="导出 EPUB">↓</button><button data-delete="${b.id}" class="quiet danger" title="删除">×</button></div></article>`}
function library(){const visible=books.filter(b=>(filter==='all'||b.status===filter)&&`${b.title} ${b.author} ${b.tags} ${b.folder}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.updated-a.updated);return `<div class="eyebrow">YOUR PERSONAL LIBRARY</div><div class="page-heading"><div><h1>我的书库</h1><p class="sub">收藏故事，也收藏属于自己的阅读时光。</p></div><button class="primary" data-action="import">＋ 导入书籍</button></div><section class="hero"><div><div class="eyebrow">FROM PLAIN TEXT TO BEAUTIFUL BOOKS</div><h2>让文字，长成一本书。</h2><p>从一份朴素的 TXT 开始，整理章节、设计版式、制作封面。<br/>把喜欢的故事，变成自己喜欢的模样。</p><div class="row"><button class="primary small" data-action="new">开始制作 →</button><button class="quiet small" data-action="sample">体验示例书</button></div></div><div class="hero-art" aria-hidden="true"><div class="mini-book">山间来信</div><div class="mini-book">慢读人间</div></div></section><div class="stats"><div class="stat"><small>藏书总数</small><b>${books.length}<span>本</span></b></div><div class="stat"><small>正在阅读</small><b>${books.filter(b=>b.status==='reading').length}<span>本</span></b></div><div class="stat"><small>已经读完</small><b>${books.filter(b=>b.status==='done').length}<span>本</span></b></div><div class="stat"><small>累计阅读时长</small><b>${(books.reduce((s,b)=>s+b.stats.seconds,0)/3600).toFixed(1)}<span>小时</span></b></div></div><div class="toolbar"><div class="tabs">${[['all','全部书籍'],['reading','在读'],['want','想读'],['done','读完']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><span class="spacer"></span><input class="search" id="search" placeholder="搜索书名、作者、标签…" aria-label="搜索书库" value="${esc(search)}"><button id="view-toggle" class="small" title="切换列表与封面墙">${list?'▦':'☷'}</button></div>${visible.length?`<div class="${list?'book-list':'books'}">${visible.map(card).join('')}</div>`:`<div class="empty"><h2>${books.length?'没有匹配的书籍':'书架已备好，等一个故事。'}</h2><p>拖入 TXT、EPUB，或先打开示例体验完整流程。</p><button data-action="import" class="primary">导入本地文件</button></div>`}<p class="footnote">支持批量导入 TXT / EPUB · UTF-8 / GB18030 / Big5 / UTF-16 · 书籍不会上传服务器</p>`}
function bindLibrary(){$$('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render()});$('#view-toggle').onclick=()=>{list=!list;render()};$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}}
function workbench(){return `<div class="eyebrow">MAKE SOMETHING WORTH KEEPING</div><div class="page-heading"><div><h1>精排工作台</h1><p class="sub">从章节结构到每一个段落，把故事整理成书。</p></div><button data-action="new" class="primary">＋ 新建项目</button></div><div class="hero"><div><h2>一份文本，无限种模样。</h2><p>自动分章、文本清理、简繁互转、组件精排、封面与字体设计。制作完成后，可在书库阅读或导出为 EPUB。</p><div class="row"><button data-action="import" class="primary small">导入 TXT / EPUB</button><button data-action="sample" class="small">打开示例</button></div></div></div><h2>最近编辑</h2>${books.length?`<div class="table-wrap"><table class="read-table"><thead><tr><th>书名</th><th>章节</th><th>更新时间</th><th>操作</th></tr></thead><tbody>${[...books].sort((a,b)=>b.updated-a.updated).map(b=>`<tr><td>${esc(b.title)}</td><td>${b.chapters.length}</td><td>${new Date(b.updated).toLocaleDateString()}</td><td><button class="small" data-open="${b.id}">继续精排</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">还没有制作项目</div>'}`}
function bindWorkbench(){}
async function openBook(id,target){currentId=id;chapterIndex=target==='reader'?Math.min(current().progress.chapter,current().chapters.length-1):0;editTab='text';undo=[];nav(target);if(target==='reader'){current().status='reading';await saveBook();startReading()}}
function editor(){const b=current(),c=b.chapters[chapterIndex];return `<div class="editor-head"><div><div class="eyebrow">BOOK DESIGN STUDIO</div><h1>${esc(b.title)}</h1><span id="save-status" class="status-text">已保存到本机</span></div><div class="row"><button id="undo" class="small">↶ 撤销</button><button id="backup-project" class="small">备份项目</button><button id="read-current" class="small">阅读预览</button><button id="export-current" class="primary small">导出 EPUB ↓</button></div></div><div class="editor-layout"><section class="panel"><h3>章节结构 <span class="status-text">${b.chapters.length} 项</span></h3><input id="chapter-search" style="width:100%;font-size:11px" placeholder="查找章节…" aria-label="查找章节"><div class="chapter-list">${b.chapters.map((ch,i)=>`<div class="chapter-row ${i===chapterIndex?'active':''}" data-chapter-row="${i}"><small>${i+1}</small><button data-chapter="${i}" title="${esc(ch.title)}">${kindNames[ch.type]==='章'?'':kindNames[ch.type]+' · '}${esc(ch.title)}</button></div>`).join('')}</div><div class="row"><button id="add-chapter" class="small">＋ 新章节</button><button id="resplit" class="small">重新分章</button></div><div class="section-label">整理全文</div><div class="row"><button id="clean" class="small">清理文本</button><button id="ads" class="small">推广过滤</button><button id="convert" class="small">简繁互转</button><button id="replace" class="small">查找替换</button></div><p class="tip">更改会自动保存。结构调整前可备份项目。</p></section><section class="panel"><div class="subnav"><button data-edit-tab="text" class="${editTab==='text'?'active':''}">正文编辑</button><button data-edit-tab="preview" class="${editTab==='preview'?'active':''}">排版预览</button><button data-edit-tab="metadata" class="${editTab==='metadata'?'active':''}">书籍信息</button><button data-edit-tab="cover" class="${editTab==='cover'?'active':''}">封面设计</button></div>${editTab==='metadata'?metadata(b):editTab==='cover'?coverEditor(b):`<label class="field">章节标题<input id="chapter-title" value="${esc(c.title)}"></label><div class="row"><select id="chapter-type" aria-label="章节类型">${Object.entries(kindNames).map(([v,n])=>`<option value="${v}" ${c.type===v?'selected':''}>${n}</option>`).join('')}</select><button id="chapter-up" class="small" title="上移">↑</button><button id="chapter-down" class="small" title="下移">↓</button><button id="merge" class="small">合并上章</button><button id="chapter-delete" class="small danger">删除</button></div>${editTab==='text'?`<div class="section-label">插入精排组件 · 选中文字后点击</div><div class="row">${[['chat','聊天'],['forum','微博 / 评论'],['social','动态'],['system','公告'],['author','作者的话'],['quote','引用'],['letter','信件'],['list','列表']].map(([v,n])=>`<button class="small" data-component="${v}">${n}</button>`).join('')}<button id="detect-components" class="small">自动识别</button><button id="component-help" class="small">格式说明</button></div>${c.originalHtml?'<p class="tip">已保留 EPUB 正文与内嵌图片。编辑此章文字后，将改用当前精排样式。</p>':''}<textarea id="chapter-text" class="edit-text" spellcheck="false" aria-label="章节正文">${esc(c.text)}</textarea><div class="row"><span id="word-count" class="status-text">${countWords(c.text).toLocaleString()} 字</span><span class="spacer"></span><button id="split-here" class="small">在光标处拆章</button></div>`:previewChapter(b,c)}`}</section><section class="panel editor-settings"><h3>版式与素材</h3><div><label class="field">阅读主题<select data-style="theme">${Object.entries(themes).map(([v,t])=>`<option value="${v}" ${b.style.theme===v?'selected':''}>${t[0]}</option>`).join('')}</select></label><label class="field">字体<select data-style="font"><option value="serif" ${b.style.font==='serif'?'selected':''}>宋体 / 衬线</option><option value="sans" ${b.style.font==='sans'?'selected':''}>黑体 / 无衬线</option>${b.fonts.map(f=>`<option value="${esc(f.name)}" ${b.style.font===f.name?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><div class="row"><button id="import-font" class="small">＋ 导入字体</button>${b.fonts.length?'<button id="remove-font" class="small">移除字体</button>':''}</div><p class="tip">TTF / OTF / WOFF / WOFF2，导出时嵌入书中。</p></div><div><div class="row"><label class="field">字号<input data-style="size" type="number" min="12" max="36" value="${b.style.size}"></label><label class="field">行高<input data-style="line" type="number" min="1.2" max="3" step=".05" value="${b.style.line}"></label></div><label class="field">标题颜色<input type="color" data-style="headingColor" value="${esc(b.style.headingColor)}"></label><label class="field">标题对齐<select data-style="titleStyle"><option value="center" ${b.style.titleStyle==='center'?'selected':''}>居中</option><option value="left" ${b.style.titleStyle==='left'?'selected':''}>居左</option></select></label><label class="field">章节修饰线<input data-style="decor" value="${esc(b.style.decor)}" placeholder="留空则不显示"></label><label class="field">组件皮肤<select data-style="componentSkin">${[['soft','柔和卡片'],['square','方角 / 报纸'],['parchment','羊皮纸']].map(([v,n])=>`<option value="${v}" ${b.style.componentSkin===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div>${[['indent','首行缩进'],['vertical','竖排文字'],['dropcap','首字放大'],['kindle','Kindle / 墨屏导出适配']].map(([v,n])=>`<label class="check-row"><input type="checkbox" data-style="${v}" ${b.style[v]?'checked':''}>${n}</label>`).join('')}<div class="section-label">本章图片</div><button id="chapter-image" class="small">${c.image?'更换':'添加'}章节头图</button>${c.image?'<button id="remove-image" class="quiet small">移除</button>':''}<p class="tip">墨屏导出使用黑白文字与简单边框。不同阅读器仍可能呈现不同效果。</p></div></section></div>`}
function metadata(b){return `${[['title','书名'],['author','作者'],['language','语言代码'],['publisher','出版者 / 制作者'],['signature','章末署名'],['folder','文件夹'],['tags','标签（逗号分隔）']].map(([k,t])=>`<label class="field">${t}<input data-meta="${k}" value="${esc(b[k])}"></label>`).join('')}<label class="field">简介<textarea data-meta="description">${esc(b.description)}</textarea></label><div class="row"><label class="field">阅读状态<select data-meta="status">${Object.entries(statusNames).map(([v,n])=>`<option value="${v}" ${b.status===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">个人评分<select data-meta="rating">${Array.from({length:6},(_,i)=>`<option value="${i}" ${Number(b.rating)===i?'selected':''}>${i?'★'.repeat(i):'未评分'}</option>`).join('')}</select></label></div>`}
function coverEditor(b){return `<div class="cover-preview">${coverHTML(b)}</div><div class="row"><button id="upload-cover" class="primary small">上传封面</button><button id="generate-cover" class="small">生成排版封面</button><button id="clear-cover" class="quiet small">清除图片</button></div><div class="section-label">封面配色</div><div class="cover-choices">${coverColors.map((v,i)=>`<button aria-label="封面配色 ${i+1}" class="swatch ${b.coverColor===v?'selected':''}" data-color="${v}" style="background:${v}"></button>`).join('')}</div><label class="field" style="margin-top:20px">封面版式<select id="cover-variant"><option value="0" ${b.coverVariant===0?'selected':''}>素笺 · 经典</option><option value="1" ${b.coverVariant===1?'selected':''}>山岚 · 光影</option><option value="2" ${b.coverVariant===2?'selected':''}>折页 · 几何</option></select></label><p class="tip">12 种配色 × 3 款版式，共 36 个基础组合。生成封面后会把书名与作者绘入图片，随 EPUB 导出。</p><div class="section-label">AI 封面</div><p class="tip">当前未接入图像生成服务。你可以上传其他工具生成的图片；这里的「生成排版封面」为本地绘制，不是 AI 生成。</p>`}
function previewChapter(b,c){const st=b.style,t=themes[st.theme]||themes.paper;return `<div class="preview theme-${esc(st.theme)} font-${esc(st.font)} ${st.vertical?'vertical':''}" style="font-size:${st.size}px;line-height:${st.line};${!['serif','sans'].includes(st.font)?`font-family:'${esc(st.font)}';`:''}" id="preview-content"><h2 style="color:${esc(st.headingColor)};text-align:${esc(st.titleStyle)}">${esc(c.title)}</h2>${c.image?`<img class="chapter-image" src="${safeData(c.image)}" alt="章节头图">`:''}${st.decor?`<div class="title-decor">${esc(st.decor)}</div>`:''}${c.originalHtml||blocksToHTML(c.text)}</div><style>#preview-content p{text-indent:${st.indent?'2em':'0'}}${st.dropcap?'#preview-content p:first-of-type:first-letter{font-size:2.3em;float:left;line-height:1.2}':''}${st.componentSkin==='square'?'#preview-content .component{border-radius:0}':st.componentSkin==='parchment'?'#preview-content .component{background:#eee2c5;color:#453b2c}':''}</style>`}
function snapshot(){undo.push(JSON.stringify(current()));if(undo.length>15)undo.shift()}
function changed(redraw=false){scheduleSave();if(redraw)render()}
function bindEditor(){const b=current(),c=b.chapters[chapterIndex];$$('[data-edit-tab]').forEach(el=>el.onclick=()=>{editTab=el.dataset.editTab;render()});$('#undo').onclick=()=>{if(!undo.length)return toast('没有可撤销的操作');const restored=JSON.parse(undo.pop());books[books.findIndex(x=>x.id===b.id)]=restored;chapterIndex=Math.min(chapterIndex,restored.chapters.length-1);saveBook(restored).then(render)};$('#backup-project').onclick=()=>downloadJSON({format:'bookloom-project',version:1,books:[b]},b.title+'.bookloom.json');$('#read-current').onclick=()=>{b.progress.chapter=chapterIndex;nav('reader');startReading()};$('#export-current').onclick=()=>exportBook(b);$('#chapter-search').oninput=e=>$$('[data-chapter-row]').forEach(el=>el.hidden=!b.chapters[Number(el.dataset.chapterRow)].title.includes(e.target.value));$$('[data-chapter]').forEach(el=>el.onclick=()=>{chapterIndex=Number(el.dataset.chapter);render()});$('#add-chapter').onclick=()=>{snapshot();b.chapters.splice(chapterIndex+1,0,{id:uid(),title:'新章节',text:'',type:'chapter',image:null});chapterIndex++;changed(true)};$('#resplit').onclick=resplit;$('#clean').onclick=cleanText;$('#ads').onclick=filterAds;$('#convert').onclick=convertChinese;$('#replace').onclick=replaceText;
 const title=$('#chapter-title');if(title)title.oninput=e=>{c.title=e.target.value;changed()};const type=$('#chapter-type');if(type)type.onchange=e=>{snapshot();c.type=e.target.value;changed(true)};
 const text=$('#chapter-text');if(text){text.onfocus=()=>{if(!text.dataset.snap){snapshot();text.dataset.snap='1'}};text.oninput=e=>{c.text=e.target.value;delete c.originalHtml;$('#word-count').textContent=countWords(c.text).toLocaleString()+' 字';changed()};$$('[data-component]').forEach(el=>el.onclick=()=>insertComponent(el.dataset.component));$('#split-here').onclick=()=>{const p=text.selectionStart;if(p<=0||p>=c.text.length)return toast('请将光标放在正文中间');snapshot();b.chapters.splice(chapterIndex+1,0,{id:uid(),title:c.title+'（续）',text:c.text.slice(p).trim(),type:'chapter',image:null});c.text=c.text.slice(0,p).trim();delete c.originalHtml;changed(true)};$('#detect-components').onclick=detectComponents;$('#component-help').onclick=()=>modal('组件文字格式',`<p class="tip">选中正文后点击组件按钮；也可直接编辑以下标记。聊天显示线稿气泡及气泡上方的人名；同一人物保持固定左右方向，输入的时间不显示。帖子头像仍为首字占位。帖子底部数据为排版内容，不是可点击的社交功能。</p><label class="field">聊天格式（我=姓名可指定右侧人物）<textarea readonly rows="7">[[chat|山间来信|我=阿青]]
小林 [09:41]：信到了吗？
旁白：阿青低头看了看手中的信。
阿青 [09:42]：到了。
阿青 [09:43]：我现在读给你听。
[[/]]</textarea></label><p class="tip">同一人物始终在同一侧。未指定「我」时，第二位出场人物放右侧。没有「姓名：」前缀的行，或「旁白：」「动作：」「神态：」开头的行，显示为灰色居中旁白。</p><label class="field">微博与楼中楼格式<textarea readonly rows="12">[[forum]]
主帖 小林 @xiaolin · 10月12日
收到了一封迟到的信。
评论 3 · 转发 2 · 点赞 12
---
阿青 @aqing · 10月12日
好想知道信里写了什么。
---
陈舟 @chenzhou 回复 @aqing · 10月12日
我也很好奇。
[[/]]</textarea></label><p class="tip">第一条为主帖，后续为评论。「昵称 @用户名 回复 @对方」会归入对方评论下的楼中楼。回复楼中楼时仍放在同一评论下，并显示被回复人。用 === 或「主帖 」开始另一篇微博。同名人物建议使用唯一 @用户名，找不到被回复人时保留为普通评论，不丢失内容。</p><label class="field">信件格式<textarea readonly rows="8">[[letter|山间来信]]
称呼：亲爱的你：

在这里写下正文，空行分隔段落。

落款：小林
日期：十月十二日
[[/]]</textarea></label>`,[['ok','知道了']])}
 const action=(id,fn)=>{const el=$(id);if(el)el.onclick=fn};action('#chapter-up',()=>moveChapter(-1));action('#chapter-down',()=>moveChapter(1));action('#merge',()=>{if(!chapterIndex)return toast('已经是第一章');snapshot();const prev=b.chapters[chapterIndex-1];prev.text+='\n\n'+c.title+'\n'+c.text;delete prev.originalHtml;b.chapters.splice(chapterIndex,1);chapterIndex--;changed(true)});action('#chapter-delete',async()=>{if(b.chapters.length===1)return toast('请至少保留一个章节');if(!await confirmModal('删除章节',`确定删除「${c.title}」及其正文？可使用撤销恢复。`))return;snapshot();b.chapters.splice(chapterIndex,1);chapterIndex=Math.min(chapterIndex,b.chapters.length-1);changed(true)});
 $$('[data-meta]').forEach(el=>el.onchange=()=>{b[el.dataset.meta]=el.dataset.meta==='rating'?Number(el.value):el.value;changed()});$$('[data-style]').forEach(el=>el.onchange=()=>{const k=el.dataset.style;b.style[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(k==='size')b.style[k]=Math.max(12,Math.min(36,b.style[k]||17));if(k==='line')b.style[k]=Math.max(1.2,Math.min(3,b.style[k]||1.95));changed(true)});
 $('#import-font').onclick=()=>$('#font').click();action('#remove-font',()=>{snapshot();b.fonts=b.fonts.filter(f=>f.name!==b.style.font);b.style.font='serif';changed(true)});$('#chapter-image').onclick=()=>{imageTarget='chapter';$('#image').click()};action('#remove-image',()=>{c.image=null;changed(true)});action('#upload-cover',()=>{imageTarget='cover';$('#image').click()});action('#generate-cover',async()=>{b.cover=await drawCover(b);changed(true);toast('封面已生成，可随 EPUB 导出')});action('#clear-cover',()=>{b.cover=null;changed(true)});$$('[data-color]').forEach(el=>el.onclick=()=>{b.coverColor=el.dataset.color;b.cover=null;changed(true)});const variant=$('#cover-variant');if(variant)variant.onchange=()=>{b.coverVariant=Number(variant.value);b.cover=null;changed(true)}}
function moveChapter(dir){const b=current(),i=chapterIndex+dir;if(i<0||i>=b.chapters.length)return;snapshot();[b.chapters[i],b.chapters[chapterIndex]]=[b.chapters[chapterIndex],b.chapters[i]];chapterIndex=i;changed(true)}
function insertComponent(kind){const el=$('#chapter-text'),c=current().chapters[chapterIndex],start=el.selectionStart,end=el.selectionEnd;const defaults={chat:'小林 [09:41]：你好，山间的信到了吗？\n阿青 [09:42]：到了，正想读给你听。\n旁白：她低头拆开了信封。\n阿青 [09:42]：是春天寄来的信。',forum:'主帖 小林 @xiaolin · 10月12日 09:41\n今天收到一封山间来信。你有没有写过信给未来的自己？\n评论 3 · 转发 2 · 点赞 12\n---\n阿青 @aqing · 10月12日 09:42\n有些故事，走回来才能读懂。\n---\n陈舟 @chenzhou 回复 @aqing · 10月12日 09:43\n你也收到过这样的信吗？\n---\n阿青 @aqing 回复 @chenzhou · 10月12日 09:44\n收到过，一直留到现在。',social:'@作者\n在这里记录一则动态。',system:'在这里输入系统公告。',author:'在这里写下作者的话。',quote:'在这里放入引用。',letter:'称呼：亲爱的你：\n\n当你读到这封信，窗外应该又是一个晴天。愿你还记得，山间总有一条路在等你回来。\n\n愿你平安，也愿你自在。\n\n落款：小林\n日期：十月十二日',list:'• 第一项\n• 第二项'};snapshot();const selected=el.value.slice(start,end)||defaults[kind];c.text=el.value.slice(0,start)+`\n[[${kind}]]\n${selected}\n[[/]]\n`+el.value.slice(end);delete c.originalHtml;changed(true)}
function modal(title,body,buttons=[['cancel','取消'],['ok','确定']]){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}<div class="row" style="justify-content:flex-end;margin-top:24px">${buttons.map(([v,n])=>`<button data-modal="${v}" class="${v==='ok'?'primary':''}">${n}</button>`).join('')}</div></section>`;document.body.append(wrap);const finish=value=>{wrap.remove();document.removeEventListener('keydown',key);resolve(value)};const key=e=>{if(e.key==='Escape')finish(null)};document.addEventListener('keydown',key);wrap.querySelectorAll('[data-modal]').forEach(el=>el.onclick=()=>{const values={};wrap.querySelectorAll('input,textarea,select').forEach((input,i)=>values[input.name||input.id||i]=input.type==='checkbox'?input.checked:input.value);finish(el.dataset.modal==='ok'?values:null)});wrap.querySelector('input,textarea,select,button')?.focus()})}
const confirmModal=async(title,text)=>!!await modal(title,`<p class="tip">${esc(text)}</p>`);
async function newProject(){const r=await modal('新建电子书',`<label class="field">书名<input name="title" value="未命名的故事" maxlength="200"></label><label class="field">作者<input name="author" placeholder="佚名"></label><label class="field">正文（也可稍后导入）<textarea name="text" rows="7" placeholder="第一章 初见\n在这里开始你的故事……"></textarea></label>`);if(!r)return;const b=newBook(r.title.trim()||'未命名的故事',r.text);b.author=r.author.trim()||'佚名';books.push(b);await saveBook(b);openBook(b.id,'editor')}
async function resplit(){const b=current();const r=await modal('重新识别章节',`<p class="tip">会根据文本重新生成章节，已设置的章节图片与原 EPUB 排版将被重置。正文会保留，操作前自动加入撤销历史。</p><label class="field">自定义章节正则（留空使用中文 / 英文章节规则）<input name="rule" placeholder="例如：^第[一二三四五六七八九十0-9]+章.*$"></label><label class="check-row"><input type="checkbox" name="includeTitles" checked>将当前标题一同用于重新分章</label>`);if(!r)return;try{const text=b.chapters.map(c=>(r.includeTitles?c.title+'\n':'')+c.text).join('\n\n');const next=splitChapters(text,r.rule);snapshot();b.chapters=next;chapterIndex=0;changed(true);toast(`已识别 ${next.length} 个章节`)}catch(e){toast('章节规则无效：'+e.message)}}
async function cleanText(){const b=current();const r=await modal('清理全文',`<label class="check-row"><input name="trim" type="checkbox" checked>清理行首行尾空格</label><label class="check-row"><input name="blank" type="checkbox" checked>合并连续空行</label><label class="check-row"><input name="join" type="checkbox">合并段内换行（请确认原文段落以空行分隔）</label><label class="check-row"><input name="titles" type="checkbox">清理正文开头重复的章节标题</label><label class="check-row"><input name="duplicate" type="checkbox">删除标题和正文均完全相同的重复章节</label>`);if(!r)return;snapshot();for(const c of b.chapters){let s=c.text;if(r.trim)s=s.split('\n').map(l=>l.trim()).join('\n');if(r.blank)s=s.replace(/\n{3,}/g,'\n\n');if(r.join)s=s.split(/\n\s*\n/).map(p=>p.replace(/(?<!\])\n(?!\[)/g,' ')).join('\n\n');if(r.titles&&s.split('\n')[0]?.trim()===c.title.trim())s=s.split('\n').slice(1).join('\n').trim();if(s!==c.text){c.text=s;delete c.originalHtml}}if(r.duplicate){const seen=new Set();b.chapters=b.chapters.filter(c=>{const key=c.title+'\0'+c.text;if(seen.has(key))return false;seen.add(key);return true})}chapterIndex=Math.min(chapterIndex,b.chapters.length-1);changed(true);toast('文本整理完成')}
async function filterAds(){const b=current();const r=await modal('识别推广文字',`<p class="tip">仅列出疑似推广段落，由你逐条确认后删除。不会自动清除正文。</p><label class="field">匹配正则<input name="rule" value="${esc('最新网址|本书由.*整理|更多.*小说.*(?:下载|关注)|请.*收藏.*网址|https?://[^\\s]+')}"></label>`);if(!r)return;let rule;try{rule=new RegExp(r.rule,'i')}catch{return toast('正则表达式无效')}const matches=[];b.chapters.forEach((c,i)=>c.text.split('\n').forEach((line,j)=>{if(rule.test(line))matches.push({i,j,line})}));if(!matches.length)return toast('没有发现匹配段落');if(matches.length>2000)return toast('匹配超过 2000 段，请缩小规则范围');const selected=await modal(`确认过滤 · ${matches.length} 段`,matches.map((m,k)=>`<label class="check-row"><input type="checkbox" name="m${k}" checked><span><b>${esc(b.chapters[m.i].title)}</b><br/>${esc(m.line)}</span></label>`).join(''));if(!selected)return;snapshot();const remove=new Map();let n=0;matches.forEach((m,k)=>{if(selected['m'+k]){if(!remove.has(m.i))remove.set(m.i,new Set());remove.get(m.i).add(m.j);n++}});for(const [i,rows]of remove){b.chapters[i].text=b.chapters[i].text.split('\n').filter((l,j)=>!rows.has(j)).join('\n');delete b.chapters[i].originalHtml}changed(true);toast(`已删除 ${n} 段推广文字`)}
async function replaceText(){const r=await modal('全文查找替换',`<label class="field">查找<input name="find"></label><label class="field">替换为<input name="replace"></label><label class="check-row"><input name="regex" type="checkbox">使用正则表达式</label>`);if(!r||!r.find)return;try{const rule=new RegExp(r.regex?r.find:r.find.replace(/[.*+?^$\{\}()|[\]\\]/g,'\\$&'),'g');let n=0;for(const c of current().chapters)n+=[...c.text.matchAll(rule)].length;if(!n)return toast('没有找到匹配内容');if(!await confirmModal('确认替换',`将替换全文中的 ${n} 处匹配。`))return;snapshot();for(const c of current().chapters){const next=c.text.replace(rule,r.replace);if(next!==c.text){c.text=next;delete c.originalHtml}}changed(true);toast(`已替换 ${n} 处`)}catch(e){toast('替换失败：'+e.message)}}
async function convertChinese(){if(!globalThis.OpenCC)return toast('简繁转换库未能加载，请刷新重试');const r=await modal('简繁互转',`<label class="field">转换方向<select name="direction"><option value="s2t">简体 → 台湾繁体</option><option value="t2s">繁体 → 大陆简体</option></select></label><p class="tip">转换全书标题与正文；原 EPUB 的局部样式会重置为本应用精排样式。建议先备份项目。</p>`);if(!r)return;snapshot();const fn=OpenCC.Converter({from:r.direction==='s2t'?'cn':'tw',to:r.direction==='s2t'?'tw':'cn'}),b=current();b.title=fn(b.title);b.author=fn(b.author);b.description=fn(b.description);for(const c of b.chapters){c.title=fn(c.title);c.text=fn(c.text);delete c.originalHtml}b.language=r.direction==='s2t'?'zh-TW':'zh-CN';changed(true);toast('简繁转换完成')}
async function detectComponents(){const c=current().chapters[chapterIndex];const r=await modal('自动识别特殊段落',`<p class="tip">将连续的「姓名：内容」识别为聊天，将「作者有话说」「系统公告」开头的段落识别为卡片。基于文本规则，可能误判；可先预览再撤销。</p><label class="check-row"><input name="chat" type="checkbox" checked>连续对话（至少两行）</label><label class="check-row"><input name="author" type="checkbox" checked>作者的话 / 系统公告</label><label class="check-row"><input name="all" type="checkbox">应用到全书（默认仅当前章节）</label>`);if(!r)return;snapshot();let n=0;for(const ch of r.all?current().chapters:[c]){if(ch.text.includes('[['))continue;let s=ch.text;if(r.chat)s=s.replace(/(^|\n)((?:[^\n:：]{1,12}[:：][^\n]+\n){1,}[^\n:：]{1,12}[:：][^\n]+)/g,(m,p,body)=>{n++;return p+'[[chat]]\n'+body+'\n[[/]]'});if(r.author)s=s.replace(/(^|\n)((?:作者有话说|作者的话|系统公告)[：:]?[^\n]*(?:\n(?!\n)[^\n]+)*)/g,(m,p,body)=>{n++;return p+`[[${body.startsWith('系统')?'system':'author'}]]\n`+body+'\n[[/]]'});if(ch.text!==s){ch.text=s;delete ch.originalHtml}}changed(true);toast(`已生成 ${n} 个组件，可在预览中查看`)}
async function drawCover(b){const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1420;const ctx=canvas.getContext('2d');ctx.fillStyle=b.coverColor||coverColors[0];ctx.fillRect(0,0,1000,1420);ctx.fillStyle='#ffffff0e';if(b.coverVariant===1){for(let i=0;i<8;i++){ctx.beginPath();ctx.ellipse(450,1300,200+i*100,150+i*70,-.4,0,Math.PI*2);ctx.fill()}}if(b.coverVariant===2){ctx.beginPath();ctx.moveTo(1000,300);ctx.lineTo(0,1420);ctx.lineTo(1000,1420);ctx.fill()}ctx.strokeStyle='#eee5c3aa';ctx.lineWidth=2;ctx.strokeRect(55,55,890,1310);ctx.strokeRect(68,68,864,1284);ctx.textAlign='center';ctx.fillStyle='#f3ead4';ctx.font='25px sans-serif';ctx.fillText('B O O K L O O M   E D I T I O N',500,180);const chars=Array.from(b.title),lines=[];for(let i=0;i<chars.length;i+=7)lines.push(chars.slice(i,i+7).join(''));ctx.font='76px serif';lines.slice(0,8).forEach((l,i)=>ctx.fillText(l,500,480+i*115,760));ctx.font='28px serif';ctx.fillText(b.author+' 著',500,1110,700);ctx.fillStyle='#f3ead488';ctx.fillRect(460,1200,80,2);return canvas.toDataURL('image/jpeg',.92)}
async function loadFonts(){for(const b of books)for(const f of b.fonts){if(document.fonts.check(`14px "${f.name}"`))continue;try{const font=new FontFace(f.name,`url(${f.data})`);await font.load();document.fonts.add(font)}catch{}}}
function reader(){const b=current(),c=b.chapters[chapterIndex];return `<div class="reader reader-layout"><div class="reader-nav"><button id="reader-back" class="quiet">← 返回书库</button><select id="reader-chapter" aria-label="选择章节">${b.chapters.map((ch,i)=>`<option value="${i}" ${i===chapterIndex?'selected':''}>${esc(ch.title)}</option>`).join('')}</select><button id="reader-options" class="quiet">Aa 设置</button></div><p class="tip">${esc(b.title)} · ${esc(b.author)} <span style="float:right">${chapterIndex+1} / ${b.chapters.length}</span></p><div class="progress-bar"><div style="width:${(chapterIndex+1)/b.chapters.length*100}%"></div></div>${previewChapter(b,c)}<div class="reader-footer"><button id="prev-chapter" ${chapterIndex===0?'disabled':''}>← 上一章</button><button id="add-note">书签 / 批注</button><button id="next-chapter">${chapterIndex===b.chapters.length-1?'标记读完 ✓':'下一章 →'}</button></div><div class="panel" style="margin-top:25px"><h3>书签与批注</h3>${b.notes.length?b.notes.map(n=>`<div class="annotation"><button class="quiet small" data-remove-note="${n.id}">×</button><b>${esc(n.chapterTitle)}</b><br/>${n.quote?`「${esc(n.quote)}」<br/>`:''}${esc(n.text)}<br/><span class="status-text">${new Date(n.date).toLocaleString()}</span></div>`).join(''):'<p class="tip">选中文字，再点击「书签 / 批注」记录想法。</p>'}</div></div>`}
function bindReader(){$('#reader-back').onclick=()=>nav('library');$('#reader-chapter').onchange=e=>readerGo(Number(e.target.value));$('#prev-chapter').onclick=()=>readerGo(chapterIndex-1);$('#next-chapter').onclick=async()=>{if(chapterIndex===current().chapters.length-1){current().status='done';current().progress.ratio=1;await saveBook();toast('又读完一个故事，已记入足迹。');nav('library')}else readerGo(chapterIndex+1)};$('#reader-options').onclick=async()=>{const st=current().style;const r=await modal('阅读设置',`<label class="field">主题<select name="theme">${Object.entries(themes).map(([v,t])=>`<option value="${v}" ${st.theme===v?'selected':''}>${t[0]}</option>`).join('')}</select></label><label class="field">字号<input name="size" type="number" min="12" max="36" value="${st.size}"></label><label class="field">行高<input name="line" type="number" min="1.2" max="3" step=".05" value="${st.line}"></label><label class="check-row"><input type="checkbox" name="vertical" ${st.vertical?'checked':''}>竖排</label>`);if(!r)return;Object.assign(st,{theme:r.theme,size:Math.min(36,Math.max(12,Number(r.size)||17)),line:Math.min(3,Math.max(1.2,Number(r.line)||1.95)),vertical:r.vertical});await saveBook();render()};$('#add-note').onclick=async()=>{const selection=window.getSelection();const quote=$('#preview-content')?.contains(selection?.anchorNode)?selection.toString():'';const r=await modal('添加书签 / 批注',`${quote?`<p class="tip">「${esc(quote.slice(0,2000))}」</p>`:''}<label class="field">想法<textarea name="text" placeholder="留下想法，或留空添加书签"></textarea></label>`);if(!r)return;const b=current();b.notes.push({id:uid(),chapter:chapterIndex,chapterTitle:b.chapters[chapterIndex].title,quote:quote.slice(0,5000),text:r.text||'书签',date:Date.now()});await saveBook();render();toast('已保存批注')};$$('[data-remove-note]').forEach(el=>el.onclick=async()=>{current().notes=current().notes.filter(n=>n.id!==el.dataset.removeNote);await saveBook();render()})}
async function readerGo(i){if(i<0||i>=current().chapters.length)return;chapterIndex=i;current().progress={chapter:i,ratio:i/Math.max(1,current().chapters.length-1)};current().status='reading';await saveBook();render();window.scrollTo(0,0)}
function startReading(){clearInterval(readTimer);readTimer=setInterval(()=>{if(page!=='reader'||document.hidden||!current())return;const b=current(),date=today();b.stats.seconds+=10;b.stats.days[date]=(b.stats.days[date]||0)+10;saveBook(b).catch(()=>{})},10000)}
function stats(){const days={};books.forEach(b=>Object.entries(b.stats.days).forEach(([d,s])=>days[d]=(days[d]||0)+s));const total=books.reduce((s,b)=>s+b.stats.seconds,0);let streak=0;const now=new Date();for(let i=0;i<10000;i++){const d=new Date(now);d.setDate(d.getDate()-i);if(days[d.toLocaleDateString('sv-SE')])streak++;else if(i===0)continue;else break}const cells=Array.from({length:182},(_,i)=>{const d=new Date();d.setDate(d.getDate()-181+i);const key=d.toLocaleDateString('sv-SE');return `<div class="${days[key]?'hot':''}" title="${key} · ${Math.round((days[key]||0)/60)} 分钟" style="${days[key]?`opacity:${Math.min(1,.35+days[key]/3600)}`:''}"></div>`}).join('');return `<div class="eyebrow">A LIFE BETWEEN THE PAGES</div><div class="page-heading"><div><h1>阅读足迹</h1><p class="sub">读过的每一页，都会留下光。</p></div></div><div class="stats"><div class="stat"><small>累计阅读</small><b>${(total/3600).toFixed(1)}<span>小时</span></b></div><div class="stat"><small>已读完</small><b>${books.filter(b=>b.status==='done').length}<span>本</span></b></div><div class="stat"><small>连续阅读</small><b>${streak}<span>天</span></b></div><div class="stat"><small>书库字数</small><b>${(allWords()/10000).toFixed(1)}<span>万字</span></b></div></div><section class="panel"><h2>近半年的阅读日历</h2><p class="tip">在本应用前台阅读时，每 10 秒记录一次时长。悬停方格可查看日期与分钟数。</p><div class="heatmap">${cells}</div><span class="tip">浅色 → 深色：阅读时间由少到多</span></section><section class="panel" style="margin-top:22px"><h2>年度阅读目标</h2><label class="field">今年想读多少本？<input id="annual-goal" type="number" min="1" max="999" value="${Number(localStorage.getItem('bookloom-goal'))||12}" style="max-width:150px"></label><p class="tip">当前书库中读完 ${books.filter(b=>b.status==='done').length} 本。目标保存在本机；当前未区分完成年份。</p></section><div class="table-wrap panel" style="margin-top:22px"><h2>每一本书的轨迹</h2><table class="read-table"><thead><tr><th>书名</th><th>阅读时长</th><th>进度</th><th>评分</th></tr></thead><tbody>${books.map(b=>`<tr><td>${esc(b.title)}</td><td>${Math.round(b.stats.seconds/60)} 分钟</td><td>${statusNames[b.status]} · 第 ${b.progress.chapter+1} 章</td><td>${b.rating?'★'.repeat(b.rating):'—'}</td></tr>`).join('')}</tbody></table></div>`}
function settings(){return `<div class="eyebrow">YOUR BOOKS, YOUR SPACE</div><div class="page-heading"><div><h1>设置与备份</h1><p class="sub">书籍保存在这个浏览器里，备份让作品长久留存。</p></div></div><div class="settings-grid"><section class="panel"><h2>数据与迁移</h2><p class="tip">书库、章节、字体、封面、阅读进度与批注均存放在本机 IndexedDB。切换设备不会自动同步。</p><div class="row"><button id="backup-all" class="primary">备份完整书库</button><button data-action="import">恢复备份</button><button id="export-all">批量导出 EPUB</button></div><p class="tip">恢复时以独立副本导入，已有书籍不被覆盖。</p><button id="persistent" class="small">申请浏览器持久存储</button><p id="storage-info" class="tip">正在检查存储空间…</p></section><section class="panel"><h2>离线与设备</h2><p class="tip">首次加载成功后，应用缓存可供离线使用。安卓 Chrome 可通过浏览器菜单添加到主屏幕。首次私有站点访问仍需完成登录。</p><p class="tip">跨设备迁移可使用完整书库备份文件。iCloud、WebDAV 和自动云同步尚未接入。</p><div class="section-label">Kindle 传书</div><p class="tip">导出 EPUB 后可使用系统分享，或到亚马逊 Send to Kindle 页面上传。当前不保存亚马逊凭据，也不会自动发送邮件。</p><a href="https://www.amazon.com/sendtokindle" target="_blank" rel="noopener">打开 Send to Kindle ↗</a></section><section class="panel"><h2>功能边界</h2><p class="tip">当前可用：TXT / EPUB 导入、批量操作、编码重读、章节管理、清理与替换、简繁转换、8 类组件、8 个主题、字体与图片、封面制作、本地书库、阅读与批注、阅读时长、备份恢复、EPUB 导出。</p><p class="tip">尚未实现：AI 图像生成、在线同步、复杂图片裁切、人物资料库、自定义头像 / 通话等高级组件、多层目录组编辑。EPUB 导入会保留安全的正文标记和图片，移除原书脚本及外部资源，不保证原样还原所有 CSS。</p></section><section class="panel"><h2>关于书织</h2><p class="tip">独立实现的电子书工坊。仅处理你主动导入的文件，不提供书籍内容。</p><p class="tip">使用 <a href="vendor/fflate-LICENSE" target="_blank">fflate（MIT）</a> 处理 EPUB，使用 <a href="vendor/opencc-LICENSE" target="_blank">OpenCC-JS（MIT）</a> 进行简繁转换。</p><p class="tip">文本编码自动检测为启发式处理。遇到乱码时请在导入确认中手动切换编码；已经丢失为问号或替代符的原文无法凭空恢复。</p></section></div>`}
function bindSettings(){$('#backup-all').onclick=()=>downloadJSON({format:'bookloom-project',version:1,books},'书织-完整书库-'+today()+'.json');$('#export-all').onclick=exportAll;$('#persistent').onclick=async()=>toast(await navigator.storage?.persist?.()?'已获得持久存储许可':'浏览器未授予持久存储，请定期备份');navigator.storage?.estimate?.().then(s=>{const el=$('#storage-info');if(el)el.textContent=`此站点已使用约 ${(s.usage/1048576).toFixed(1)} MB，可用配额约 ${(s.quota/1048576).toFixed(0)} MB。`})}
document.addEventListener('change',e=>{if(e.target.id==='annual-goal')localStorage.setItem('bookloom-goal',String(Math.max(1,Number(e.target.value)||12)))});
function download(data,name,type='application/octet-stream'){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function downloadJSON(data,name){download(JSON.stringify(data),name,'application/json')}
async function exportBook(b){if(!b)return;try{if(!globalThis.fflate)throw Error('EPUB 处理库未加载');const exportCopy=structuredClone(b);if(!exportCopy.cover)exportCopy.cover=await drawCover(exportCopy);const bytes=makeEpub(exportCopy,fflate.zipSync);download(bytes,b.title+'.epub','application/epub+zip');toast('EPUB 已导出，手机可从下载列表分享至 Kindle')}catch(e){toast('导出失败：'+e.message)}}
async function exportAll(){if(!books.length)return toast('书库为空');await withBusy('正在打包书库…',async()=>{const files={};for(const [i,b]of books.entries()){const copy=structuredClone(b);if(!copy.cover)copy.cover=await drawCover(copy);files[`${i+1}-${b.title.replace(/[<>:"/\\|?*]/g,'_')}.epub`]=makeEpub(copy,fflate.zipSync)}download(fflate.zipSync(files),'书织-EPUB合集.zip','application/zip');toast('已打包所有书籍')})}
async function withBusy(message,fn){if(busy)return;busy=true;const overlay=document.createElement('div');overlay.className='busy-overlay';overlay.textContent=message;document.body.append(overlay);await new Promise(r=>setTimeout(r,30));try{await fn()}catch(e){toast(e.message||'操作失败')}finally{busy=false;overlay.remove()}}
async function deleteBook(id){const b=books.find(b=>b.id===id);if(!await confirmModal('删除书籍',`确定删除「${b.title}」及本机进度和批注？删除前建议先备份。`))return;await new Promise((resolve,reject)=>{const tx=db.transaction('books','readwrite');tx.objectStore('books').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});books=books.filter(b=>b.id!==id);if(currentId===id)currentId=null;render();toast('书籍已删除')}
async function importFiles(fileList){if(!fileList.length)return;for(const file of fileList){try{if(file.size>100*1024*1024)throw Error(`${file.name} 超过 100 MB，请先拆分`);if(/\.json$/i.test(file.name)){await restoreBackup(file);continue}if(/\.epub$/i.test(file.name)){await withBusy('正在解析 EPUB…',async()=>{const b=await importEpub(new Uint8Array(await file.arrayBuffer()),file.name);books.push(b);await saveBook(b)});continue}if(!/\.txt$/i.test(file.name)){toast('仅支持 TXT、EPUB 和书织 JSON 备份');continue}const bytes=new Uint8Array(await file.arrayBuffer());const decoded=decodeText(bytes);let text=decoded.text,encoding=decoded.encoding;const r=await modal('导入 TXT · '+file.name,`<label class="field">文本编码<select id="encoding" name="encoding">${['utf-8','gb18030','big5','utf-16le','utf-16be'].map(v=>`<option value="${v}" ${encoding===v?'selected':''}>${v.toUpperCase()}</option>`).join('')}</select></label><label class="field">开头预览<textarea id="encoding-preview" readonly rows="6">${esc(text.slice(0,1500))}</textarea></label><p class="tip">若文字不正常，请更换编码。文件仅在当前浏览器处理。</p>`);setTimeout(()=>{},0); // the encoding selector is bound by the delegated listener below
 if(!r)continue;text=decodeText(bytes,r.encoding).text;const b=newBook(file.name.replace(/\.txt$/i,''),text);b.encoding=r.encoding;books.push(b);await saveBook(b);toast(`已导入「${b.title}」· ${b.chapters.length} 章`)}catch(e){toast(`${file.name}：${e.message}`)}}nav('library')}
let pendingEncodingBytes=null;
$('#files').onchange=async e=>{const files=[...e.target.files];e.target.value='';await importFilesWithEncoding(files)};
async function importFilesWithEncoding(files){for(const file of files){pendingEncodingBytes=/\.txt$/i.test(file.name)?new Uint8Array(await file.arrayBuffer()):null;await importFiles([file]);pendingEncodingBytes=null}}
document.addEventListener('change',e=>{if(e.target.id==='encoding'&&pendingEncodingBytes){try{$('#encoding-preview').value=decodeText(pendingEncodingBytes,e.target.value).text.slice(0,1500)}catch(err){toast(err.message)}}});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();document.body.classList.add('drop-active')}});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('drop-active')});document.addEventListener('drop',async e=>{e.preventDefault();document.body.classList.remove('drop-active');if(!busy)await importFilesWithEncoding([...e.dataTransfer.files])});
async function restoreBackup(file){const data=JSON.parse(await file.text());if(data.format!=='bookloom-project'||data.version!==1||!Array.isArray(data.books))throw Error('不是有效的书织备份');data.books.forEach(validateBook);if(!await confirmModal('恢复书库',`将导入 ${data.books.length} 本书为独立副本。`))return;for(const entry of data.books){const b=normalize(entry);b.id=uid();b.chapters.forEach(c=>{c.id=uid();if(c.originalHtml)c.originalHtml=sanitizeHTML(c.originalHtml)});b.style=normalizeStyle(b.style);b.cover=safeData(b.cover)||null;b.chapters.forEach(c=>c.image=safeData(c.image)||null);b.fonts=b.fonts.filter(f=>typeof f.name==='string'&&/^[\w\u3400-\u9fff .-]{1,100}$/.test(f.name)&&/^data:(font\/[^;]+|application\/octet-stream);base64,/.test(f.data)&&/^(ttf|otf|woff|woff2)$/.test(f.ext));books.push(b);await saveBook(b)}toast(`已恢复 ${data.books.length} 本书`)}
function normalizeStyle(st){const base=defaultStyle();return {...base,theme:themes[st.theme]?st.theme:'paper',font:/^[\w\u3400-\u9fff .-]{1,100}$/.test(st.font)?st.font:'serif',size:Math.min(36,Math.max(12,Number(st.size)||17)),line:Math.min(3,Math.max(1.2,Number(st.line)||1.95)),indent:!!st.indent,vertical:!!st.vertical,dropcap:!!st.dropcap,decor:String(st.decor||'').slice(0,100),headingColor:/^#[0-9a-f]{6}$/i.test(st.headingColor)?st.headingColor:base.headingColor,titleStyle:['left','center'].includes(st.titleStyle)?st.titleStyle:'center',componentSkin:['soft','square','parchment'].includes(st.componentSkin)?st.componentSkin:'soft',kindle:!!st.kindle}}
function safePath(base,relative){const parts=(base.slice(0,base.lastIndexOf('/')+1)+decodeURIComponent(relative.split('#')[0])).split('/'),out=[];for(const p of parts){if(p==='..')out.pop();else if(p&&p!=='.')out.push(p)}return out.join('/')}
async function importEpub(bytes,name){if(!globalThis.fflate)throw Error('EPUB 处理库未加载');let total=0;const files=fflate.unzipSync(bytes,{filter:f=>{if(f.originalSize>60*1024*1024)throw Error('EPUB 内单文件过大');total+=f.originalSize;if(total>200*1024*1024)throw Error('EPUB 解压总量超过 200 MB');return true}});const text=p=>{if(!files[p])throw Error('EPUB 缺少文件：'+p);return new TextDecoder().decode(files[p])};const parse=(s,type='application/xml')=>{const doc=new DOMParser().parseFromString(s,type);if(doc.querySelector('parsererror'))throw Error('EPUB XML 格式错误');return doc};const container=parse(text('META-INF/container.xml'));const opfPath=container.getElementsByTagName('rootfile')[0]?.getAttribute('full-path');if(!opfPath)throw Error('EPUB 缺少内容索引');const opf=parse(text(opfPath));const getTag=t=>opf.getElementsByTagNameNS('*',t)[0]?.textContent||'';const b=newBook(getTag('title')||name.replace(/\.epub$/i,''));b.author=getTag('creator')||'佚名';b.description=getTag('description');b.language=getTag('language')||'zh-CN';b.publisher=getTag('publisher');b.source='epub';const items=new Map([...opf.getElementsByTagName('item')].map(el=>[el.getAttribute('id'),el]));const imgData=path=>{const bytes=files[path];if(!bytes)return null;const ext=path.split('.').pop().toLowerCase();const mime={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',gif:'image/gif',webp:'image/webp'}[ext];if(!mime)return null;let bin='';for(let i=0;i<bytes.length;i+=8192)bin+=String.fromCharCode(...bytes.subarray(i,i+8192));return `data:${mime};base64,${btoa(bin)}`};const cover=[...items.values()].find(el=>(el.getAttribute('properties')||'').split(' ').includes('cover-image'));const coverId=[...opf.getElementsByTagName('meta')].find(el=>el.getAttribute('name')==='cover')?.getAttribute('content');const coverItem=cover||items.get(coverId);if(coverItem)b.cover=imgData(safePath(opfPath,coverItem.getAttribute('href')));b.chapters=[];for(const ref of opf.getElementsByTagName('itemref')){const item=items.get(ref.getAttribute('idref'));if(!item||item.getAttribute('media-type')!=='application/xhtml+xml')continue;const path=safePath(opfPath,item.getAttribute('href'));const doc=new DOMParser().parseFromString(text(path),'text/html');const body=doc.body;for(const img of body.querySelectorAll('img')){const src=imgData(safePath(path,img.getAttribute('src')||''));if(src)img.setAttribute('src',src);else img.remove()}const title=body.querySelector('h1,h2,h3')?.textContent?.trim()||doc.title||`第 ${b.chapters.length+1} 章`;const heading=body.querySelector('h1,h2,h3');if(heading)heading.remove();const html=sanitizeHTML(body.innerHTML);const plain=htmlToText(html);if(!plain.trim()&&!html.includes('<img'))continue;b.chapters.push({id:uid(),title,text:plain,type:'chapter',image:null,originalHtml:html})}if(!b.chapters.length)throw Error('未发现可阅读的 EPUB 章节');return b}
function sanitizeHTML(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','DIV','SPAN','BR','H1','H2','H3','H4','H5','H6','B','STRONG','EM','I','U','S','BLOCKQUOTE','UL','OL','LI','HR','IMG','SUP','SUB','RUBY','RT','RP','TABLE','TBODY','TR','TD','TH','CAPTION','SECTION']);doc.querySelectorAll('script,style,iframe,object,embed,svg,math,link,meta,form,input,button,audio,video,source').forEach(el=>el.remove());for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue}for(const attr of [...el.attributes]){if(el.tagName==='IMG'&&attr.name==='src'&&safeData(attr.value))continue;if(attr.name==='class'&&/^[\w -]{1,100}$/.test(attr.value))continue;if(['colspan','rowspan'].includes(attr.name)&&/^\d{1,2}$/.test(attr.value))continue;el.removeAttribute(attr.name)}}const xml=new XMLSerializer();return [...doc.body.childNodes].map(n=>xml.serializeToString(n)).join('')}
function htmlToText(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('br').forEach(el=>el.replaceWith('\n'));doc.querySelectorAll('p,div,section,li,h1,h2,h3,blockquote,tr').forEach(el=>el.append('\n'));return doc.body.textContent.replace(/\n{3,}/g,'\n\n').trim()}
$('#image').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||!current())return;try{if(file.size>20*1024*1024)throw Error('请选择小于 20 MB 的图片');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.9);snapshot();if(imageTarget==='cover')current().cover=data;else current().chapters[chapterIndex].image=data;changed(true)}catch(err){toast(err.message)}};
$('#font').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||!current())return;try{if(file.size>20*1024*1024)throw Error('字体超过 20 MB');const ext=file.name.split('.').pop().toLowerCase();if(!['ttf','otf','woff','woff2'].includes(ext))throw Error('暂不支持 TTC 字体集合，请使用 TTF / OTF / WOFF');const bytes=new Uint8Array(await file.arrayBuffer());let bin='';for(let i=0;i<bytes.length;i+=8192)bin+=String.fromCharCode(...bytes.subarray(i,i+8192));const name=file.name.replace(/\.[^.]+$/,'').replace(/[^\w\u3400-\u9fff .-]/g,'').slice(0,80)||'自定义字体';snapshot();current().fonts=current().fonts.filter(f=>f.name!==name);current().fonts.push({name,ext,data:`data:font/${ext};base64,${btoa(bin)}`});current().style.font=name;changed(true);toast('字体已导入，将随 EPUB 嵌入')}catch(err){toast(err.message)}};
async function addSample(){const existing=books.find(b=>b.sample);if(existing)return openBook(existing.id,'editor');const b=newBook('山间来信',`第一卷 风起的地方\n每个故事，都从一封没有署名的信开始。\n\n第一章 雨后的邮局\n雨停在午后。小镇的邮局门前，青石板上还映着一片湿润的天光。\n\n小林推开门，看见柜台上放着一封淡绿色的信。信封没有邮票，只有一句话：请在春天结束之前，读完它。\n\n[[chat]]\n小林：今天有我的信吗？\n阿青：有一封，从山里来的。\n小林：山里？谁寄的？\n阿青：也许是春天吧。\n[[/]]\n\n她笑了笑，把信小心地放进口袋。窗外的梧桐叶被风翻过一页，像一本正在醒来的书。\n\n[[quote]]\n有些话，要走过很长的路，才会抵达一个人的心里。\n[[/]]\n\n第二章 山路与回声\n小林沿着河岸向北走去。远山有雾，近处的青草还带着雨水的清香。\n\n[[forum|小镇论坛 · 春日来信]]\n1楼 · 楼主\n有人收到过没有邮票的信吗？\n2楼 · 山客\n收到过。记得沿着溪流往上走。\n3楼 · 匿名\n答案有时候藏在你走过的路上。\n[[/]]\n\n她把帖子读了两遍，终于决定上山。\n\n[[system|旅途提示]]\n新的地点已解锁：听风亭。\n请记得带上那封信。\n[[/]]\n\n第三章 春天的署名\n亭子里没有人。只有一只旧木箱，和一面被岁月磨亮的铜镜。\n\n[[social|阿青的动态]]\n今天替一个人寄出了等了十年的信。\n希望她走到山顶时，能看见自己的春天。\n♡ 12 · 评论 3\n[[/]]\n\n小林拆开信封。信纸上，竟是自己十年前写下的字迹。\n\n[[author]]\n感谢你读到这里。愿每一个曾经写信给未来的人，都能收到温柔的回音。\n[[/]]\n\n[[list|春日心愿]]\n• 读完一本喜欢的书\n• 给未来的自己写封信\n• 在雨后走一段山路\n[[/]]`);b.author='书织编辑室';b.description='一封来自春天的信，一段关于阅读与重逢的短篇。此示例文本为应用演示创作。';b.tags='示例,短篇';b.sample=true;b.coverColor='#425b48';books.push(b);await saveBook(b);openBook(b.id,'editor')}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
init().catch(e=>{$('#app').innerHTML=`<main><h1>本地书库未能打开</h1><p>${esc(e.message)}</p><p>请使用正常浏览模式，并允许此站点使用浏览器存储。</p></main>`});
